CREATE OR REPLACE FUNCTION public.rpc_perf_report(p_session text, p_build text, p_device text, p_minutes jsonb, p_spikes jsonb DEFAULT '[]'::jsonb, p_world uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := auth.uid(); v_spikes jsonb := '[]'::jsonb;
begin
  perform private.pace(auth.uid(), 'deal');
  perform private.once();
  if me is null or jsonb_typeof(p_minutes) is distinct from 'array' then return; end if;
  if jsonb_array_length(p_minutes) = 0 or jsonb_array_length(p_minutes) > 60 or octet_length(p_minutes::text) > 65536 then
